def b91decode(strng):
    decoding_table = {char: i for i, char in enumerate('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"')}
    b = 0
    n = 0
    result = b''
    for char in strng:
        v = decoding_table[char]
        b |= v << n
        n += 13
        while n >= 8:
            result += bytes([(b & 255)])
            b >>= 8
            n -= 8
    return result.decode('latin-1')

class Solution:
    def numTimesAllBlue(self, light):
        n = len(light)
        right_max = 0
        count = 0
        for i in range(n):
            right_max = max(right_max, light[i])
            if right_max == i + 1:
                count += 1
        return count

