class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        def find_partner(person):
            for p1, p2 in pairs:
                if p1 == person:
                    return p2
                if p2 == person:
                    return p1
            return None

        def prefers(person, u, y):
            pref_list = preferences[person]
            for pref in pref_list:
                if pref == u:
                    return True
                if pref == y:
                    return False
            return False

        unhappy = set()
        for x in range(n):
            y = find_partner(x)
            for u in range(n):
                if x == u:
                    continue
                v = find_partner(u)
                if prefers(x, u, y) and prefers(u, x, v):
                    unhappy.add(x)
                    unhappy.add(u)

        return len(unhappy)

