class Solution:
    def minSwaps(self, grid: list[list[int]]) -> int:
        n = len(grid)
        grid_copy = [row[:] for row in grid]
        swaps = 0
        for i in range(n):
            required_zeros = n - 1 - i
            j = i
            while j < n:
                count = 0
                for k in range(n - 1, -1, -1):
                    if grid_copy[j][k] == 0:
                        count += 1
                    else:
                        break
                if count >= required_zeros:
                    break
                j += 1

            if j == n:
                return -1

            for k in range(j, i, -1):
                grid_copy[k], grid_copy[k - 1] = grid_copy[k - 1], grid_copy[k]
                swaps += 1

        return swaps
